<?php
namespace LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Illuminate\Support\Str; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Policy; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\AuditService; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\SettingStore;
class SettingsController extends Controller { public function edit(SettingStore $s){return view('iapm::admin-settings',['values'=>['dry_run'=>$s->get('dry_run',true),'default_policy_id'=>$s->get('default_policy_id'),'sms_default_receiver'=>$s->get('sms_default_receiver'),'retention_days'=>$s->get('retention_days',365),'notification_timeout'=>$s->get('notification_timeout',15),'notification_retry_count'=>$s->get('notification_retry_count',2),'deleted_port_behavior'=>$s->get('deleted_port_behavior','recover'),'url_base'=>$s->get('url_base',config('app.url')),'uplink_port_group_id'=>$s->get('uplink_port_group_id'),'aggregate_threshold'=>$s->get('aggregate_threshold',0),'aggregate_window_seconds'=>$s->get('aggregate_window_seconds',120),'has_token'=>filled($s->get('ingestion_token'))],'policies'=>Policy::orderBy('name')->get(),'portGroups'=>\App\Models\PortGroup::orderBy('name')->get(['id','name'])]);} public function update(Request $r,SettingStore $s,AuditService $audit){abort_unless($r->user()->can('manage iapm settings'),403);$d=$r->validate(['dry_run'=>['nullable','boolean'],'default_policy_id'=>['nullable','exists:iapm_policies,id'],'sms_default_receiver'=>['nullable','string','max:128'],'retention_days'=>['required','integer','between:1,3650'],'notification_timeout'=>['required','integer','between:1,300'],'notification_retry_count'=>['required','integer','between:0,10'],'deleted_port_behavior'=>['required','in:recover,retain'],'url_base'=>['nullable','url:http,https','max:2048'],'uplink_port_group_id'=>['nullable','integer','exists:port_groups,id'],'aggregate_threshold'=>['required','integer','between:0,1000'],'aggregate_window_seconds'=>['required','integer','between:30,3600']]);$d['dry_run']=$r->boolean('dry_run');foreach($d as $k=>$v)$s->put($k,$v);$audit->record($r,'updated','settings',null,null,$d);return back()->with('status','Settings updated.');} public function rotateToken(Request $r,SettingStore $s,AuditService $audit){abort_unless($r->user()->can('manage iapm settings'),403);$old=$s->get('ingestion_token');if($old){$s->put('previous_ingestion_token',$old);$s->put('previous_ingestion_token_expires_at',now()->addMinutes(15)->toIso8601String());}$token=Str::random(64);$s->put('ingestion_token',$token);$audit->record($r,'rotated_token','settings',null,null,['ingestion_token'=>'[REDACTED]','previous_token_expires_at'=>now()->addMinutes(15)->toIso8601String()]);return back()->with('new_ingestion_token',$token)->with('status','Token rotated. The previous token remains valid for 15 minutes. Copy the new token now.');} }
